/* Read-only operating guide and setup checklist. Only existing GET project records are read. */
(() => {
  'use strict';
  const node=id=>document.getElementById(id),text=v=>String(v??''),arr=v=>Array.isArray(v)?v:[];
  const count=v=>typeof v==='number'&&Number.isInteger(v)&&v>=0?v:null;
  const state={active:false,sequence:0,pending:null,loading:false,error:'',projects:[],project:'',progress:null,dossier:null,projectQuery:'',query:'',section:'',printing:false};
  const button=(action,label,id='',tab='')=>`<button type="button" data-guide-action="${esc(action)}" data-guide-id="${esc(id)}"${tab?` data-guide-tab="${esc(tab)}"`:''}>${esc(label)}</button>`;
  const option=(value,label,current)=>`<option value="${esc(value)}"${value===current?' selected':''}>${esc(label)}</option>`;
  const badge=(status,label)=>`<span class="fg-badge fg-${esc(status)}">${esc(label)}</span>`;
  // This HTML is maintained with the application. API values are never inserted into a topic body.
  const topics=[
    {id:'start',title:'Start here: orders and files',summary:'Three focused entry screens, an assembly register, and tools for the selected work.',route:'order-setup',link:'Open Orders',body:`
      <p>Start in <strong>Orders</strong>. Open an existing P.O. or choose <strong>New P.O.</strong>. New-order setup follows <strong>P.O. number → GPN &amp; assemblies → Spools &amp; welds</strong>. Choose <strong>Save P.O.</strong> directly on the spool screen. Files remain available afterward. The main menu keeps <strong>Orders</strong>, <strong>Production progress</strong>, <strong>Scan &amp; transfer</strong>, <strong>Process flow</strong> and <strong>Guide</strong> close at hand.</p>
      <p>The saved P.O. shows a flat assembly register with separate GPN and Assembly Number fields. Select one assembly to open its spool table, files and physical copies. The compact toolbar contains <strong>Files &amp; BOMs</strong>, <strong>Spool QR labels</strong> and <strong>Production progress</strong>. The P.O.'s <strong>More tools</strong> retains <strong>Production records</strong>, <strong>Spool records &amp; Excel</strong> and <strong>Job Packets</strong>; the secondary <strong>GPN records</strong> section keeps GPN management separate.</p>
      <p><strong>More tools</strong> contains specialist screens, including Projects &amp; welds, Spool parts, Audit readiness and Job Packets. Administrator tools and Export Excel appear there for authorized employees. Individual spool records still link to their own welds, material records, documents and production actions.</p>
      <p>Use <strong>Back</strong> to return within FabTrace. In order setup it moves to the previous step and keeps your entries. Closing an unfinished setup offers <strong>Resume setup</strong> while the page remains open. The document window has its own Back and return-to-spool controls.</p>`},
    {id:'signin',title:'1. Sign in and know who records each decision',summary:'Employee badges, private PINs, roles and accountable records.',route:'items',link:'Open Items',body:`
      <p>Sign in with your assigned <strong>employee badge ID and private PIN</strong>. An item QR opens its shared record after login. An employee QR identifies a badge; it does not sign that person in or prove that they accepted a handoff. Use your own account for work and decisions. In <strong>Scan &amp; handoff</strong>, identify the item, scan the sending employee’s badge and the receiving employee’s badge into their separate fields, then select a destination and current work status. The sender must match the recorded custodian; the signed-in recorder is shown separately. Both badge fields are cleared for every new transfer.</p><p>Use the separate <strong>Scan sender badge</strong> and <strong>Scan receiver badge</strong> buttons for a phone camera, or use a handheld QR scanner and press Enter. Manual badge ID entry remains available. A standalone employee QR link asks whether it identifies the sender or receiver unless you already selected that role for the current item. If custody changes during entry, refresh and identify both badges again.</p><p>The location list includes standard work centers and <strong>Keep current location</strong>, which retains the actual recorded location. Shop Foremen and administrators can add, rename or deactivate actual shop locations under <strong>Manage shop locations</strong>. Previous custody events retain their historical information.</p>
      <div class="tablewrap"><table><caption>Role responsibilities</caption><thead><tr><th>Role</th><th>Typical responsibilities</th></tr></thead><tbody>
      <tr><td>Material coordinator</td><td>Receive and track material, select and allocate parts, record permitted production handoffs, and manage logistics timing. This position does not record physical welding or approve quality.</td></tr>
      <tr><td>Fit-up welder</td><td>Record fit-up and tack operations, the fit-up traveler step, and assigned fit-up evidence and timing.</td></tr>
      <tr><td>Process welder</td><td>Record root, fill/cap and weld completion, the process-welding traveler step, and assigned production-welding evidence and timing.</td></tr>
      <tr><td>Painter</td><td>Record sandblast/paint work and the coating process, and submit the permitted coating records for QA/QC review.</td></tr>
      <tr><td>Fab Prep Technician</td><td>Record component preparation, cutting/beveling and assigned finishing work. Painting and welding remain separate job permissions.</td></tr>
      <tr><td>Pressure Testing Technician</td><td>Record pressure-test receipt, the actual report PASS/FAIL, required correction, pressure-phase timing and permitted pressure-test Job Packet records. QA/QC reviews the results and records acceptance.</td></tr>
      <tr><td>NDT</td><td>Record NDT receipt, the actual report PASS/FAIL, required correction, NDT-phase timing and permitted NDT Job Packet records. QA/QC reviews the results and records acceptance.</td></tr>
      <tr><td>Shop Foreman</td><td>Manage projects, plans, templates and requirements; import items; manage logistics, holds and repairs; configure Job Packets and submit packet/audit evidence. Physical trade work uses the appropriate job role.</td></tr>
      <tr><td>QA/QC</td><td>Submit and review quality evidence, record dimensional inspections, resolve holds, review source applicability, approve final release and issue packets.</td></tr>
      <tr><td>Administrator</td><td>All tracking capabilities, employee access and private PIN administration, explicit administrative release and return-to-work decisions, custody corrections, full Excel export and changes to Job Packet gate flags.</td></tr>
      </tbody></table></div><p>All active staff can read this guide and the setup checklist and use ordinary badge handoffs. The originating screen and server enforce each action's job permissions. Numbered-step actions also follow their displayed responsible roles; QA decisions remain restricted to QA/QC and administrators. An administrator assigns each employee's position through <strong>Employees → Change position</strong> or <strong>Admin controls → Employee accounts</strong>. A position or badge does not establish a welding or inspection qualification.</p>`},
    {id:'order-setup',title:'2. Set up a P.O., assemblies and spools',summary:'P.O. number, GPN and assembly quantities, then spools and weld counts with a direct save.',route:'order-setup',link:'Open Orders',body:`
      <ol><li><strong>P.O. number:</strong> open <strong>Orders → New P.O.</strong>, enter the number and continue.</li><li><strong>GPN &amp; assemblies:</strong> enter <strong>GPN</strong>, the required <strong>Assembly Number</strong> and the assembly quantity. Both identifiers are required for every assembly. Use the actual assembly number from the job records, add a row for each assembly, then continue.</li><li><strong>Spools &amp; welds:</strong> beneath each assembly, enter <strong>Spool number</strong>, <strong>Qty per assembly</strong> and <strong>Welds per spool</strong>. Add spool rows as needed. Quantities describe one assembly; weld counts apply to each physical copy. Enter zero only when a spool has no welds. Check the calculated totals and choose <strong>Save P.O.</strong> on this screen.</li></ol>
      <p>The saved P.O. opens a <strong>flat assembly register</strong> with separate GPN, Assembly Number and quantity fields. Select one exact assembly to show its spool table, files and physical copies. A sole assembly opens automatically. With several assemblies, use the register to select the work you need; files and physical records stay attached to their exact saved scope.</p>
      <p><strong>Assembly Number is required when creating or editing an assembly.</strong> Older records missing that number remain visible as <strong>Assembly Number required</strong>. Select the exact record and use <strong>Edit assembly</strong> to enter its actual number with a reason before further assembly setup changes. The GPN and internal <strong>ASM-…</strong> tracking ID are not substitutes, and FabTrace does not invent a number. Existing physical identities, documents and inspection history remain retained. A standalone <strong>GPN record</strong> can still exist without an assembly.</p>
      <p>When files are ready, choose <strong>Files &amp; BOMs</strong> in the toolbar, or use <strong>Upload drawing or BOM</strong> in the selected assembly's panel. Select a PDF, photo or scan; for a prepared Excel or CSV BOM, open <strong>BOM &amp; drawings</strong> beside its corresponding spool. Reading starts automatically. Add every drawing page in order, check detected spool matches and material rows, and save. Document uploads are separate saves, so retrying a file does not create another P.O.</p>
      <p>A full isometric creates a viewable complete drawing and a separate Excel BOM for each selected matching spool. A photo or scan of only a material table is saved as a BOM source with its Excel material list. If a spool number is missing or unclear, select the correct destination before saving. Check uncertain OCR readings, especially fractional cut lengths. A file that cannot be recognized can still be kept using the appropriate document choice.</p>
      <p>Open a spool's <strong>BOM &amp; drawings</strong> to view its files and use <strong>Download Excel BOM</strong>. Use <strong>Create spool BOMs</strong> to read a saved drawing again. On a unique physical spool, <strong>Use for all assembly spools</strong> opens the corresponding setup review. Setup files are inherited by physical copies registered to that exact requirement; individual document revisions keep their own scope. File-ready labels stay visible after reloading the order.</p>
      <p>Example: 3 assemblies containing spool A × 2 and spool B × 1 require <strong>6 of A and 3 of B</strong>, or <strong>9 total spools</strong>. If A has 6 welds and B has 4 welds, each physical copy receives its own weld records. A generated Excel BOM lists materials for <strong>one spool</strong>. Identifiers such as 000123 keep their leading zeros.</p>
      <p>The toolbar keeps <strong>Production progress</strong> and <strong>Spool QR labels</strong> close at hand. The P.O.'s <strong>More tools</strong> retains <strong>Production records</strong>, <strong>Spool records &amp; Excel</strong>, <strong>Job Packets</strong>, workflow guidance and permitted restore/removal actions. The label screen shows existing QR labels and remaining quantities. A generation request checks current scope and production locks before creating missing copies and their initial weld records; follow any blocker shown. Opening or printing labels does not itself create copies. Saving setup records quantities; it creates no physical items, completed work or QA approval.</p>
      <p>Use the secondary <strong>GPN records</strong> section for <strong>Add GPN</strong>, <strong>Edit GPN</strong> and the permitted GPN removal. Use <strong>Add assembly</strong> to enter another assembly or <strong>Edit assembly</strong> for its separate identity. A corrected GPN label applies to its linked assemblies while their numbers, physical identities and history remain separate. Existing <strong>Add assembly</strong> and <strong>Edit quantities &amp; welds</strong> use the identity/quantity screen followed by the spool/weld screen and direct save. Quantity edits require eligible scope and a reason. Physical assembly history locks initial quantity changes, including retained removed records; <strong>Set weld counts</strong> opens only eligible missing counts. Undeclared counts show <strong>Not entered</strong>. Ordinary setup uses identifiers and quantities while existing descriptions remain retained.</p>
      <p>Explicit uploaded <strong>Heat Number</strong> and <strong>MTR Reference</strong> facts initialize matched physical pieces. Shared setup BOMs need an exact numbered-copy target or an explicit all-copies declaration; multiple pieces need individual rows or explicit all-pieces scope. Missing or unassigned facts stay blank. An existing pinned material register needs review before a replacement BOM is adopted; its earlier facts and inspection history remain retained. Uploading a file does not approve an inspection.</p>
      <p>Setup does not choose the testing route. In <strong>Process flow</strong>, the current assembly step 17 requires <strong>YES or NO</strong>. YES follows NDT, separate QA/QC, Floor, pressure testing, separate QA/QC and Floor before Paint; NO goes to Paint with unused review/floor steps marked not required. A failed test review returns to its recorded previous station and sender and requires recorded correction and retesting. Complete child scope before the first decision; correction and testing restarts do not unlock it. Historical routes keep their saved rules.</p>`},
    {id:'spool-arrival',title:'Receive a spool: each material piece and QA/QC',summary:'Separate saved pieces, QA-001 Pass/Fail per piece, then overall arrival approval.',route:'orders',link:'Open physical spool records',body:`
      <p>Open the physical spool's <strong>BOM &amp; drawings → BOM</strong> and confirm its full readable label, such as <strong>643-777-PCW-03-01-[001]</strong>. The table shows every physical piece separately, with <strong>QA-001 Pass/Fail</strong> at the end of its row. A quantity-two flange line becomes two quantity-one rows. Shared setup BOMs ask you to choose the numbered copy when several copies exist.</p>
      <p>Select <strong>Pass</strong> to open the inspection fields. Heat numbers and MTR references may both remain blank during receiving and fabrication. Any missing required evidence is identified with a <strong>Go to field</strong> shortcut. If you edit the material details, <strong>Save material details &amp; Pass</strong> saves the piece and its inspection together. To record a completed inspection of all pieces on the selected spool, use <strong>PASS ALL</strong> in <strong>QA-001 · All pieces</strong>, optionally add inspection notes or a report/checklist reference, and choose <strong>Confirm PASS ALL</strong>. Save any material edits first; an unsaved or changed material basis stops the entire batch. Blank heat numbers and MTR references do not block receiving QA. Each piece retains its own decision and history.</p>
      <ol><li>Confirm the structured <strong>BOM for one physical spool</strong>. Use <strong>BOM &amp; drawings</strong> to upload or extract it, or use the reference inherited from the exact order requirement. If a newer upload needs review, choose <strong>Use this BOM for this spool</strong> on this page and enter a reason. Its new register uses explicit correctly scoped source facts, leaves unknown fields blank and starts with pending decisions, retaining earlier history.</li><li>A line with <strong>quantity 2 creates two saved material records</strong>. Check each piece's identifier and any imported <strong>heat number</strong> and <strong>MTR reference</strong>. Enter or correct actual facts as needed; both may remain blank through step 14 — Complete Welds and become mandatory at step 15 — QA/QC-003 - Inspect Welds. Save edits with a reason. A manual edit on one piece is not copied to another.</li><li>In <strong>Materials &amp; QA/QC</strong>, use <strong>Upload MTR</strong> or <strong>Scan a page</strong> to attach the certificate, keeping every page in order. Match its reference to the relevant material rows. A controlled paper/external certificate reference can also be verified; a file upload alone is not an inspection.</li><li><strong>QA/QC or an administrator</strong> selects <strong>QA-001 Pass or Fail for each individual piece</strong> and chooses <strong>Save QA-001</strong>. <strong>Pass</strong> needs no failure reason; inspection notes and a report/checklist reference are optional. <strong>Fail</strong> requires an inspection reference and failure reason. Each decision automatically records the inspector, time and reviewed evidence. Neither choice is preselected. Pass needs that piece's saved physical material record and current BOM. Heat numbers and MTR references may both be deferred until QA/QC-003; Fail can record missing required evidence or defects.</li><li>When every piece has a current QA-001 Pass, open <strong>Materials &amp; QA/QC</strong> and record the spool's separate <strong>overall arrival Pass</strong> after checking identity, BOM and condition. If any heat number or MTR reference is missing, its respective verification checkbox is omitted and the inspection explicitly records that verification was deferred. Confirm the heat-marking or MTR check when all of its required values are present. The arrival Pass also allows optional inspection notes and a report/checklist reference. Piece decisions do not approve the whole spool automatically.</li></ol>
      <p><strong>Pending, Failed and Needs reinspection block production and release.</strong> Correct the discrepancy, repeat affected piece checks and record a new overall arrival decision. An administrator's release override cannot skip these requirements. <strong>View QA-001 history</strong> shows earlier piece decisions.</p>
      <p><strong>After fabrication, before QA/QC-003:</strong> enter the actual heat number and MTR reference for every material piece and both sides of each weld. Entering or correcting either value changes the reviewed evidence, so repeat affected piece QA, arrival inspection and weld verification as prompted. Completed physical weld work remains recorded; a metadata update does not invent a new welding operation. QA/QC-003, later release and the Job Packet require complete heat and MTR traceability.</p>
      <p>Changed material, BOM, drawing or relevant MTR evidence can invalidate piece acceptance and the overall arrival Pass. Affected running work pauses. Explicitly adopting a replacement BOM initializes only its correctly scoped source facts and leaves unknown values blank, preserving the previous source, register and history. After approval, use <strong>Resume</strong> where applicable. Existing records receive no invented heat numbers or QA decisions during an upgrade.</p>
      <p>The bar beneath <strong>Welds per spool</strong> shows current-cycle completed welds across all required physical copies. Missing copies stay unfinished. Zero required welds and a 100% weld bar do not grant receiving approval or final release.</p>`},
    {id:'po-labels',title:'Generate a readable QR label for every spool',summary:'Permanent spool-number-[001] codes, separate physical records and stable reprinting.',route:'order-setup',link:'Open Purchase orders',body:`
      <ol><li>Open a saved P.O. and choose <strong>Spool QR labels</strong> in the toolbar or selected assembly.</li><li>Keep all assemblies selected or choose the exact record shown with its GPN and Assembly Number. Review the existing labels and remaining physical quantity.</li><li>To request missing records, enter the actual location and select the responsible employee. Each generation request checks the current scope and production locks; follow any blocker shown. Successful generation creates physical copies and their initial declared welds. Administrators and Shop Foremen can generate; other active employees can view and reprint.</li><li>Choose <strong>Print labels</strong> at 100% scale or Save as PDF. Use Next 100 for later pages. Viewing and reprinting existing labels creates no physical records.</li></ol>
      <p>Eighteen first copies of spool <strong>643-777-PCW-03-01</strong> receive <strong>643-777-PCW-03-01-[001]</strong> through <strong>643-777-PCW-03-01-[018]</strong>. Each full code is saved permanently. The sequence continues for the same spool number across P.O.s. Removed spools keep their numbers reserved, and replacements receive new numbers.</p>
      <p>Reprinting, sorting or reopening never renumbers a spool. Its original internal ID, welds, materials and history stay intact, and older printed QR links still open the same record. Labels show the readable code, P.O., GPN, and the actual Assembly Number. Use <strong>Edit assembly</strong> to correct an older missing Assembly Number; a GPN or tracking ID is not substituted. The internal assembly ID and employee assignment are omitted from the label. <strong>Print labels</strong> refreshes label data, and <strong>Download label</strong> saves the full printable image. View the spool's item record for its current assignment and custody history. The screen's <strong>Technical ID</strong> reveals the retained spool ID when needed. A legacy blank spool number keeps its old code until a real number is entered; a numbered alias fixes that spool number.</p>
      <p>Only individual spools receive QR labels. Missing parent assemblies are created automatically to keep exact ownership. Each declared weld count creates <strong>W01, W02 and onward</strong> under that physical spool. A valid inherited uploaded BOM also creates material-piece records and initializes explicit source Heat/MTR facts only for correctly scoped pieces. Missing or unassigned facts stay blank. These actions do not record inspections, completed work or arrival approval.</p>
      <p>Generate another batch if records remain. Older undeclared weld counts stay marked for setup. Printing waits for all QR images; a failed image keeps printing disabled.</p>`},
    {id:'scope',title:'Register physical assemblies and spools after setup',summary:'Physical QR identities, custody, weld plans and existing production records.',route:'orders',link:'Open Production records',body:`
      <p>First check the existing physical records: <strong>Spool QR labels</strong> may already have created the copies and their initial weld records. Open those copies instead of registering duplicates. Use <strong>P.O. workspace</strong> to return to the saved quantities and files.</p>
      <ol><li><strong>P.O:</strong> a Shop Foreman or administrator opens <strong>Orders → More tools → Production records</strong> and uses the detailed order form when an existing project must be connected. To use existing work, select <strong>Existing project to connect</strong>, confirm the customer and Job Packet P.O, and record the reason.</li><li><strong>Assembly:</strong> choose <strong>Register physical assembly</strong> for an eligible saved assembly definition or <strong>Add assembly</strong> for legacy unplanned work. Confirm its separate Assembly Number and GPN, required spool count, actual location and current custodian. FabTrace generates the physical assembly tracking ID. <strong>More options</strong> contains a custom tracking ID, drawing or existing-assembly choice. Save once to register the physical assembly and open its spools.</li><li><strong>Spools:</strong> choose <strong>Open spools</strong> beside an existing row. Use <strong>Set assembly weld plan</strong> to declare its actual weld scope and drawing revision; a zero-weld plan needs a written reason. If physical spools are still missing, use the permitted registration and linking controls for their exact scope.</li><li>Open <strong>Files, Excel &amp; other records → Edit component plan</strong> beside a physical spool to enter component requirements in <strong>Spool parts</strong>. Register and allocate the actual Part records, then follow their numbered routes. This component plan is separate from the uploaded reference BOM and its material-piece facts. Confirm both against the approved source.</li></ol>
      <p>An older assembly definition without a quantity plan can show <strong>Finish setup</strong>; a planned definition uses its saved count. Existing physical assemblies retain their IDs and history. A different older assembly part number is shown as retained information. Multiple physical copies remain separate traceable rows under the same assembly definition and GPN.</p>
      <p>Each assembly shows <strong>Spools needed</strong>, <strong>Linked</strong>, <strong>Still to link</strong> and a <strong>Ready for assembly</strong> bar. The ready percentage uses the required count; missing spools remain incomplete. A required count creates no physical items or QA records. Correct a P.O.-managed count while the assembly is unreleased and before its traveler starts; it cannot fall below existing links. For a spool with an established traveler, use the assembly's available <strong>Process flow</strong> linking action before its first step 17 testing decision, after the spool has completed its route and has current ordinary QA readiness. Assembly child scope locks after the initial YES/NO decision and stays locked through rework and testing restarts.</p>
      <p>A free-text job name on an item does not create a structured project assignment. Progress recognizes a structured plan, a linked component parent, or an exact legacy project ID; it does not guess from similar names. Selecting a project here never changes membership.</p>
      <p>For <strong>Bulk import &amp; QR labels</strong>, download the CSV template, use a registered handler badge, and review the validation preview. Item descriptions are not required. Older CSV files with a description column are still accepted. Quantity creates independent physical records. Leave the tracking ID blank when quantity is greater than one. Duplicate part numbers are allowed; tracking IDs must be unique. The current limits are 500 items per row and 10,000 per CSV.</p>
      <p>Print imported labels in batches of 100, at 100% scale, and test one QR before applying the batch. An administrator must configure the deployed public HTTPS address for working QR links. Enrollment preserves the item's identity and history; old aggregate weld totals do not become individual joint evidence.</p>`},
    {id:'removals',title:'Remove or restore a saved record',summary:'Separate GPN, assembly, spool requirement and physical-copy removal with retained history.',route:'order-setup',link:'Open Orders',body:`
      <ol><li>Sign in as an <strong>administrator</strong>. In the saved P.O., choose <strong>Remove GPN</strong>, <strong>Remove assembly</strong>, <strong>Remove spool entry</strong>, <strong>Remove copy</strong> or <strong>Remove P.O.</strong> for the exact record. Inside an eligible editor, <strong>Remove saved spool</strong> opens the same requirement preview; a draft row's <strong>Remove row</strong> only discards that unsaved row.</li><li>Review the affected entries. A GPN includes its linked assembly definitions; removing one assembly keeps its sibling assemblies separate. A P.O. includes its project scope; an assembly includes its linked descendants. Enter the displayed number exactly and add a reason before confirming.</li><li>Removed records leave the working lists. Their identities, documents, QR history, requirements, links, production and quality evidence remain readable. New work, transfers and approvals are blocked until restoration.</li><li>Open <strong>Removed records / restore</strong>, select the original group and choose <strong>Restore</strong>. Review current capacity and scope, enter its number and a reason, then confirm. Earlier independent removals stay removed.</li></ol>
      <p>A saved spool requirement can be removed only before physical assembly history exists, including retained removed history; the final active requirement cannot be removed alone. An untouched generated copy may be eligible after its and its parent's evidence is checked. Removing a copy leaves the ordered demand intact, and a replacement can fill it. Restore cannot exceed that capacity. Other linked children follow existing controlled unlinking or containing-assembly removal. Open process timers must close normally; removal does not finish fabrication or pass a quality hold point.</p>
      <p>Removed identities remain reserved. Restore the existing record to reuse it. The administrator's full Excel export contains <strong>Removed record states</strong> and the retained originals. Active P.O. BOM downloads omit removed branches.</p>`},
    {id:'parts',title:'3. Plan required parts and follow their quantities',summary:'Required physical pieces, assigned QR IDs, received parts, preparation progress and shortages.',route:'parts',link:'Open Spool parts',body:`
      <p>Open <strong>More tools → Spool parts</strong>, or use the parts action on a planned spool. A Shop Foreman or administrator creates its parts list from the approved BOM or drawing: part number if used, description, required whole pieces, and the source revision. Record the reason for every change. Pipe length belongs in the description or supporting record; the quantity is a count of physical pieces.</p>
      <p>Required quantities do not create inventory. Register actual parts through Items or <strong>Bulk import &amp; QR labels</strong>; each physical piece receives a unique tracking ID and QR. A handler, Shop Foreman or administrator can assign eligible registered parts to a required line by scanning or entering one QR/ID per line. A supplied part number must match the physical part exactly. One QR cannot stand for several pieces or satisfy two spools.</p>
      <div class="tablewrap"><table><caption>Parts quantity measures</caption><thead><tr><th>Measure</th><th>Meaning</th></tr></thead><tbody><tr><td>Required</td><td>Approved number of physical pieces needed for this spool.</td></tr><tr><td>Assigned</td><td>Unique existing Part records allocated to the required lines.</td></tr><tr><td>Received</td><td>Assigned pieces with an actual recorded receipt step. An earlier historical baseline does not invent a receipt.</td></tr><tr><td>Prepared for fit-up</td><td>Assigned pieces with current recorded preparation step 7 and return step 8, a completed component route, and no current blockers.</td></tr><tr><td>Still to assign</td><td>Required pieces without an allocated physical QR record. Unassigned or missing quantities stay incomplete.</td></tr></tbody></table></div>
      <p>Open a line's physical pieces to see each current process, handler, location, missing record and blocker. Required quantities are the denominator of these parts bars; the Project progress screen separately counts registered physical items. Preparation does not grant weld acceptance, final release or packet approval.</p>
      <p>Reconcile existing linked but unallocated components before starting fit-up. Required scope and assignments lock as production progresses. Before selection, <strong>Unassign part from spool</strong> removes both its line allocation and parent component link using a documented correction; its physical ID, traveler and history remain registered. After scope locks, follow the listed production/rework controls rather than changing quantities to hide missing work.</p>`},
    {id:'welds',title:'4. Plan joints and record actual welding',summary:'Weld identity, both-side material traceability, WPS and production operations.',route:'tracking',link:'Open Projects & welds',body:`
      <p>Define each planned joint with its permanent spool-local number, joint type, size and units, wall/schedule, drawing revision and location. Record the actual component or piece/lot identity on <strong>both material sides</strong>. Heat numbers and MTR references for both sides may remain blank through step 14 — Complete Welds, but both must be entered before step 15 — QA/QC-003 - Inspect Welds. Record the WPS identifier and revision, plus evidence for the manual qualification-applicability review.</p>
      <p>Each new weld starts with material traceability, procedure/qualification, fit-up, visual examination, NDE-plan/extent and final weld-QA controls. A Shop Foreman or administrator adds the applicable source clauses, examinations, hold points and spool-level requirements. The template is a starting point; the approved job documents determine the obligations.</p>
      <ol><li>Record fit-up and obtain the before-welding approvals.</li><li>Record the configured operations: normally root followed by fill/cap, or the approved fill/cap-only sequence.</li><li>Use <strong>Mark weld complete</strong> after the required operations are recorded.</li><li>Obtain current post-work reviews and individual weld QA acceptance, then the spool's dimensional review and final release.</li></ol>
      <p>The authenticated recorder and server time identify each operation. A process timer or checked traveler box does not manufacture a weld operation. Missing defined joints remain release blockers, even if the recorded joints are complete.</p>`},
    {id:'evidence',title:'5. Submit evidence, review it, and handle changes',summary:'Evidence is separate from acceptance; holds, repairs, revisions and release.',route:'tracking',link:'Open Projects & welds',body:`
      <p><strong>Record evidence</strong> in weld tracking stores an identifiable report reference or HTTP(S) link, reported result and notes. It does not upload the report bytes. Keep the original under document control and upload it in Job Packets when a controlled file is required. Evidence submissions await a separate inspector/administrator decision.</p>
      <p>Use non-applicability only where explicitly allowed, with a meaningful reason and authorization reference. Core material, procedure, fit-up, visual and final-QA controls cannot be waived. A failing result cannot be hidden by selecting N/A. Changed evidence or later physical work invalidates affected approvals while retaining history.</p>
      <p>A Shop Foreman, inspector or administrator can place a hold; an inspector or administrator resolves it. Use <strong>Open repair</strong> for actual rewelding: the same joint starts another work cycle and needs fresh operations and reviews. A generic rework or traveler failure does not silently claim that rewelding occurred.</p>
      <p>Ordinary QA final release needs complete planned scope, current satisfied requirements, a passing dimensional record after the latest work, and no blocking holds/rework. Released records remain locked until a permitted administrative reopen. The numbered route still permits its specified later custody/shipping steps. Administrators can separately record an administrative release with a reason in <strong>Admin controls</strong>; this retains actual outstanding work and quality records.</p>`},
    {id:'flow',title:'6. Follow the numbered flow and read the timers',summary:'25 current steps, visible testing branches, retained historical routes and elapsed time.',route:'flow',link:'Open Process flow',body:`
      <p>New travelers use <strong>CLM-25-v1</strong>. Each component uses steps <strong>1–8</strong>, each spool <strong>9–16</strong>, and each new assembly traveler <strong>17–25</strong>. A Shop Foreman or administrator starts the correct route after the required physical identity and project plan exist. Step 17, <strong>Determine if Spool need to be sent to Testing</strong>, requires an explicit <strong>YES or NO</strong>; neither is preselected. The map shows both branches. Material coordinator, Shop Foreman or Administrator verifies the assembly and scans each linked child spool exactly once at this decision. Complete assembly joining work and settle child scope before the first decision. Scope stays locked through later correction and restart cycles.</p>
      <p><strong>YES:</strong> NDT at 17 → <strong>QA/QC-004 NDT</strong> at 18 → Floor at 19 → pressure testing at 17 → <strong>QA/QC-005 pressure</strong> at 18 → Floor at 19 → Paint/finishing at 20. <strong>NO:</strong> continue to 20; testing steps 18/19 are <strong>Not required</strong> and excluded from applicable progress totals. No test or inspection pass is created by NO, and shipment Floor step 23 remains required. Testing and finishing remain on the assembly traveler; a completed child spool links to its parent process.</p>
      <p>The NDT employee or Pressure Testing Technician records receipt using the required badge handoff, then the actual technician report <strong>PASS or FAIL</strong>, report reference and handoff to QA/QC. A non-admin employee receives using their own badge. The recorded testing employee or an administrator submits the report and correction. QA/QC or an administrator records a separate, explicit <strong>PASS or FAIL</strong> for each test attempt. A failed technician report cannot receive QA PASS. Current dimensions, applicable evidence and earlier required NDT proof must support acceptance. Each QA PASS requires its actual Floor handoff before the next phase. Requirements scheduled for Final release remain due at <strong>QA/QC-006</strong>.</p>
      <p><strong>QA FAIL:</strong> record the failure details and reference, then scan the return to the <strong>exact previous testing station and employee who sent the attempt into QA/QC</strong>. The destination is shown by the server. Completed correction, a fresh test report and fresh QA review are required. An existing YES cannot become NO on rework. A corrected pressure failure carried through fresh NDT remains open until pressure QA resolves it.</p>
      <p>When changed construction or source evidence requires another cycle, a Shop Foreman or administrator uses <strong>Return to testing</strong> where it is offered, with a reason and reference. Availability follows the server's current state. A pending QA attempt needs its disposition first, and mandatory correction must be completed before restart. Earlier reports, failures and corrections remain in the history; cycle and attempt labels distinguish the new work.</p>
      <p>Use the current step's observations, full spool-code or retained-ID scan, and report reference. At a handoff step, identify both the sending and receiving badges and choose the destination and current work status from the lists. The sending employee must match the recorded custodian. The same person can move an item to a different location or record a changed work status; the form identifies this as a same-custodian update. Current steps 8, 12, 16, 19 and 23 are <strong>Return to Floor</strong> handoffs. Step 3 captures storage location without a custody handoff. Work status is an operational record; it does not advance the numbered route, pause its timer, approve an inspection, or release the item. Use the current step and timing controls for those actions. Future steps cannot be completed out of order. Steps 2, 11, 15, 18 and 22 require QA/QC or Administrator. Passing the applicable release checkpoint still uses the underlying release rules.</p>
      <p><strong>Flow progress:</strong> Inventory → QA/QC-001 → Prep/Fabrication → QA/QC-002 → Floor → Process Welder → QA/QC-003, then the recorded YES/NO testing route above. Paint is followed by <strong>QA/QC-006 → Floor → Ready To Ship</strong>. Floor is the recorded return destination after preparation, welding, each passing test review and final paint inspection. Numeric step 18 counts once in overall progress; the two test-review stations show their separately recorded phase results.</p>
      <p>The Individual spools by process board lists every numbered copy at its recorded station, such as 643-777-PCW-03-01-[001] in Inventory with black text. New spools stay in Inventory until an actual station transfer or location capture is recorded. Opening a QR record, awaiting or approving QA, and advancing a numbered step do not move a spool. In <strong>Scan &amp; transfer</strong>, choose the exact destination, including the numbered QA/QC checkpoint, and confirm the transfer for that individual copy.</p>
      <p>The individual spool number carries the color: Inventory is black, Prep/Fabrication red, Floor yellow, Process Welder blue, Testing orange, Painting pink, and Ready To Ship green. QA/QC checkpoints retain the preceding station color. Station names and flow-chart labels use neutral text. Open a saved <strong>P.O.</strong> to see every registered copy directly beneath its planned spool number, with its station and <strong>Text color</strong> designation. Select a colored number to open that copy’s process record.</p>
      <p>A recorded Ready To Ship station can still show <strong>Release blocked</strong> while required work or approvals remain outstanding. If an older generic QA/QC or custom location cannot identify an exact station, <strong>Confirm station</strong> appears beside the last known station; choose the exact station on the next actual transfer. Earlier movement and inspection history remain available.</p>
      <div class="tablewrap"><table><caption>QA checkpoints · CLM-25-v1</caption><thead><tr><th>Step / phase</th><th>Displayed check</th></tr></thead><tbody><tr><td>2</td><td>QA/QC-001 · Check Dimensions</td></tr><tr><td>11</td><td>QA/QC-002 · Check Dimensions</td></tr><tr><td>15</td><td>QA/QC-003 · Inspect Welds</td></tr><tr><td>18 / NDT</td><td>QA/QC-004 · Verify NDT Results</td></tr><tr><td>18 / pressure</td><td>QA/QC-005 · Verify Pressure Test Results</td></tr><tr><td>22</td><td>QA/QC-006 - Final Inspection</td></tr></tbody></table></div>
      <p>The current flow has 25 numbered steps, with separate phase names for the repeated testing numbers. Per-piece QA-001, overall spool arrival approval and a component's numbered traveler inspection are separate recorded actions. A physical spool needs its current piece checks and overall arrival Pass before production starts or resumes.</p>
      <p><strong>Historical travelers:</strong> retained <strong>CLM-24-v6</strong> routes keep final QA/QC-005 at 22, ready-to-ship at 23 and shipment at 24. Existing records without a catalog value remain on that frozen route. Saved events, earlier Release to Testing (Hydro/UT) labels, permitted return choices and timer visits are not renumbered or rewritten into new test decisions. New starts receive CLM-25-v1; each retained traveler keeps its saved testing obligations.</p>
      <p>For existing work, an authorized starting baseline needs its real reference and reason. Earlier steps remain <strong>Not recorded</strong>. Do not invent past completions to make the bar reach 100%. A failed inspection records an exception and returns through its permitted earlier steps; affected later completions and approvals reopen.</p>
      <p>The step or testing-phase timer moves automatically. <strong>Pause / record delay</strong> and <strong>Resume</strong> separate running and paused durations. Current testing controls follow the phase roles: NDT controls NDT work/correction, Pressure Testing Technician controls pressure work/correction, QA/QC controls the QA review, and Material coordinator/Shop Foreman controls decision and Floor phases. Administrator can control each phase. Manual <strong>Production process</strong> timing supports Start, Move, Pause, Resume and Finish for eligible enrolled spools; it cannot bypass a numbered route. Elapsed = running + paused calendar time, including nights and weekends if left running. It continues through logout and is not crew labor time. A quality hold and a paused timer are separate records.</p>
      <p>On the current route, <strong>23 — Return to Floor</strong> records the actual scanned handoff after final paint inspection; <strong>24 — Release to Ready to Ship</strong> records shipping-area movement and shipping documents; <strong>25 — Ship to Customer</strong> records the actual carrier, shipment reference and destination. These shipment actions are separate from fabrication progress through 22. A separate <strong>Confirm delivery</strong> action records the actual receipt and recipient. Physical product shipment/delivery is separate from packet handover.</p>`},
    {id:'audit',title:'7. Prepare Audit readiness with the five prompts',summary:'Requirement, CLM response, supporting documentation, evidence, and corrective actions.',route:'quality',link:'Open Audit readiness',body:`
      <p>A Shop Foreman or administrator creates a CLM-wide or project-scoped workspace. A starter matrix copies draft prompts; it creates no customer approval. Work through these five sections for each requirement:</p>
      <ol><li><strong>Customer requirement:</strong> actual expectation, source document/revision/clause, and project/PO applicability.</li><li><strong>CLM response:</strong> a supportable statement of the practice actually implemented.</li><li><strong>Supporting documentation:</strong> the exact controlled QMS, SOP, flow, policy or other revision.</li><li><strong>Required evidence:</strong> actual dated records demonstrating the requirement.</li><li><strong>Gaps and corrective actions:</strong> owner, due date, containment, cause, implementation and effectiveness records.</li></ol>
      <p>Administrators, Shop Foremen and inspectors submit audit records; inspectors and administrators review them. A source must be confirmed against the actual governing documents. Document approval, completed training, accepted evidence and requirement verification are distinct decisions. An approved schedule is not a completed audit; an alert template is not an issued Quality Alert.</p>
      <p>Use actual occurrence dates and measured results. Close corrective actions only after accepted implementation/effectiveness evidence and required customer dispositions. <strong>Ready for review</strong> does not mean <strong>Verified</strong>. New revisions, changed evidence or reopened actions can invalidate current verification.</p>
      <p>Optional project requirements can gate pre-coating steps 20/21 or the traveler's ready-to-ship/shipment positions: 24/25 on the current route, 23/24 on retained 24-step routes. They start with no production gate. CLM-wide organizational requirements do not impose a project production gate by themselves.</p>`},
    {id:'production-progress',title:'Follow all P.O.s from Inventory to Finish',summary:'A P.O. dropdown, expandable assemblies, individual spools and parts, and recorded process stages.',route:'production-progress',link:'Open Production progress',body:`
      <ol><li>Open <strong>Production progress</strong> and use the <strong>P.O.</strong> dropdown to select <strong>All P.O.s</strong> or one order.</li><li>Expand a P.O., its assembly entries identified by separate GPN and Assembly Number, then the individual spools and component parts. Every physical item shows its own progress and current process.</li><li>Expand an item to inspect <strong>Inventory, Prep, Fit-up, Welding, Assembly and Finish</strong>. Only the steps applicable to its own route count toward its bar. Shipping and delivery are separate milestones; the parent rows show the later work containing that item.</li><li>Use search and status filters to locate a particular record. The full-scope summary stays stable while the visible rows are filtered. Open <strong>Process flow</strong> or <strong>Item &amp; QR</strong> to use the existing work screens.</li></ol>
      <p>Missing required spools, incomplete material assignments, open holds and undeclared scope stay visible. Earlier baseline steps remain unrecorded, and rework reopens the affected steps. Read the scope warning and physical finish status alongside the recorded-step percentage.</p><p><strong>Project detail</strong> retains the earlier project progress screen, including projects that are not yet enrolled in a P.O.</p>`},
    {id:'progress',title:'8. Interpret project detail without hiding missing scope',summary:'Registered parts, recorded work, physical release, issued packets and handover.',route:'progress',link:'Open Project detail',body:`
      <div class="tablewrap"><table><caption>Different measures answer different questions</caption><thead><tr><th>Measure</th><th>What it proves</th></tr></thead><tbody>
      <tr><td>Recorded route / weld progress</td><td>Recorded completed route steps or joints compared with the item's declared plan. Approved historical baselines remain unrecorded.</td></tr>
      <tr><td>Registered parts finished</td><td>Current fabrication/preparation is finished for the known physical records. Each component, spool and assembly is counted separately.</td></tr>
      <tr><td>Current issued Job Packet</td><td>QA issued the complete applicable evidence package and it still matches the current records.</td></tr>
      <tr><td>Packet dispatch / receipt</td><td>An actual transfer, followed by a separately recorded acknowledgement, for an exact project revision and channel.</td></tr>
      </tbody></table></div>
      <p>The project percentage is not weighted labor, tonnage or contract value. Missing BOM items are not assumed complete. Zero registered items never mean finished. <strong>Finished</strong> includes items later shipped or delivered; those movements also have separate filters.</p>
      <p>Use project, work-package, type, status, search and sort controls to inspect the real records. A valid physical release can coexist with a recorded-route bar below 100% after an approved historical baseline. A finished spool can still need controlled files or packet QA review.</p>`},
    {id:'packet-setup',title:'9. Configure Job Packets and upload controlled files',summary:'Expected packet count, source applicability, 8 MiB files and revision control.',route:'dossier',tab:'documents',link:'Open project files',body:`
      <p>In <strong>More tools → Job Packets</strong>, a Shop Foreman or administrator configures the actual manufacturer/contact, purchase order, work order, advisements and approved source/PO reference. Declare the complete <strong>expected spool / assembly packet count</strong>. Preparation components are represented through their parent records and do not add to this count. Reconcile the intended scope with the registered plans.</p>
      <p>An inspector or administrator separately confirms current source applicability. Configuration and the built-in catalog are not source approval. Relevant PO/source changes invalidate the old review. An administrator controls changes to the coating/shipping packet gate and required customer shipment-approval flags; select these from the actual project obligations.</p>
      <p>Use <strong>Upload actual document</strong> with a consistent code, title, real revision, section and reference. Choose a shared project record or the exact spool/assembly. Shared originals can support multiple packets without duplicating the uploaded file.</p>
      <p>Supported uploads are PDF, PNG, JPG/JPEG, TXT, CSV, XLSX and DOCX. Limits: <strong>8 MiB per file</strong> and <strong>256 MiB of retained uploads per project</strong>. File identity, SHA-256, uploader and time are retained; retrieval requires login.</p>
      <p>Upload a revision under the same code and scope to preserve earlier bytes and supersede the prior revision. Select the new exact file IDs and obtain renewed reviews. An external evidence URL is a reference; the application does not fetch it into the packet. File availability alone does not prove that every required record is present or technically accepted.</p>`},
    {id:'packet-checks',title:'10. Review 25 checks across ten CLM sections',summary:'Actual measurements, selected files, QA/N/A decisions and coating/shipment gates.',route:'dossier',link:'Open spool & assembly checklists',body:`
      <p>The <strong>25 detailed checks</strong> organize the eight master Job Packet contents from <strong>Kelvion QF-QAS-100 Rev B, page 8</strong> into ten CLM sections. The ten-section organization is CLM's layout. Review the actual approved customer revisions and project amendments.</p>
      <ol class="fg-sections"><li><strong>01 Identification:</strong> manufacturer, PO, advisements, contents, drawings and product data.</li><li><strong>02 Material traceability:</strong> BOM/kit, both-side heat/MTR allocation and original files.</li><li><strong>03 Welding records:</strong> weld maps, operations, WPS, qualifications and applicable joining forms.</li><li><strong>04 Inspection and NDE:</strong> ITP, VT, applicable NDE method/extent, coverage and reports.</li><li><strong>05 Dimensional and assembly:</strong> current measurements, child scope and applicable torque records.</li><li><strong>06 Pressure testing:</strong> covered package/item IDs, actual pressure/duration and units, approved plan/instrument and approval reference.</li><li><strong>07 Nonconformance control:</strong> holds, failures, NCRs, repairs, dispositions and retests.</li><li><strong>08 Blasting and coating:</strong> preparation/environment, coating system, batch, actual DFT/instrument and applicable holiday results.</li><li><strong>09 Final release and shipping:</strong> current QA release, preservation, packaging, lifting and shipping paperwork.</li><li><strong>10 Certifications and approvals:</strong> applicable certificates/calibration/shelf life, written customer hold releases and pre-shipment authorization.</li></ol>
      <p>Record actual findings and typed results, reference the supporting record, and select its exact uploaded revisions. QA separately accepts, rejects or approves permitted non-applicability. N/A needs its scope reason and source/authorization reference; mandatory controls cannot be waived. The checklist percentage counts accepted checks and approved N/A decisions; separate physical, source and scope blockers still apply.</p>
      <p>When enabled, packet controls gate <strong>20/21</strong> on current source and applicable pressure-test/customer-hold decisions for the assembly and child scope. Steps <strong>23/24</strong> require current final release and current issued item/child packets, including required written customer shipment approval. Existing weld, child, dimensional and optional Audit readiness gates still apply. The software does not choose engineering acceptance limits or a universal NDE percentage.</p>`},
    {id:'issue',title:'11. Issue item packets, then the completed project',summary:'Immutable revisions, declared scope, current approval and stale history.',route:'dossier',tab:'issues',link:'Open issued project packages',body:`
      <ol><li>Finish actual fabrication/preparation and required inspections. Resolve the item's full blocker list, including source applicability and physical QA release.</li><li>An inspector or administrator issues the complete item packet with the real authorization reference and basis. Issue child-spool packets before their parent assembly packet.</li><li>Confirm the registered spool/assembly count equals the declared expected count. Every registered physical part must have resolved planning and current finished fabrication/preparation.</li><li>Confirm every intended spool/assembly has a current QA-issued packet. QA then issues a completed-project revision identifying the exact included item revisions.</li></ol>
      <p>An issued snapshot retains its records, selected file identities and hash. Later evidence, relevant work, rework, superseded files or scope changes can make current approval stale; they do not rewrite the issued snapshot. Review the changed evidence, renew the affected decisions and issue a new revision.</p>
      <p>A historical project issue and its receipts remain available as history. They do not prove that the changed project is currently complete or that the new revision has been delivered. A 100% checklist alone does not clear separate source, scope, physical-release or child-packet blockers.</p>`},
    {id:'handover',title:'12. Print, transfer and acknowledge the exact revision',summary:'ZIP, paper cover plus item packets and appendices; separate digital/physical records.',route:'dossier',tab:'handovers',link:'Open handover & receipts',body:`
      <p><strong>Digital:</strong> download the issued project ZIP, review its readable packet, manifest and selected original files, and transmit it using the approved customer portal, email or document-transfer method. <strong>Downloading does not dispatch the packet.</strong> The handover form records an event; it does not send files or email.</p>
      <p><strong>Physical:</strong> print the exact project revision's cover, controlled index and handover sheet. Print each exact included item-packet revision from its retained link and include the selected original supporting documents as appendices. Browser Print / Save PDF prints these views; it does not merge every original PDF, image, Word file and spreadsheet into one PDF.</p>
      <p>After delivery actually occurs, record <strong>Digital</strong> or <strong>Physical</strong> handover against the exact current completed-project revision, with recipient, organization, actual date, transfer/delivery reference and details. Record the other channel separately if the approved handover plan calls for it. An absent optional channel is not automatically a contract failure.</p>
      <p>After actual acknowledgement, record the recipient, actual receipt date and signed/portal/email reference for that dispatch. <strong>Not dispatched</strong>, <strong>Dispatched</strong> and <strong>Received</strong> are distinct. Receipt is not automatic customer technical approval. A new project revision requires its own transfer records; previous transfers stay linked to their original revision. Product shipment/delivery remains in Process flow.</p>`},
    {id:'excel',title:'13. Create an Excel BOM and export the records',summary:'Physical spool records, component BOMs, planning templates and administrator exports.',route:'orders',link:'Open Production records',body:`
      <p>For physical-spool history, open <strong>More tools → Spool records &amp; Excel</strong> in the P.O. workspace, or <strong>Order resources → Spool records Excel</strong> in Production records. Choose <strong>Export spool records</strong> and select the numbered copies. One spool downloads a workbook; multiple spools download separate workbooks in a ZIP. Each keeps seven sheets: <strong>Spool Record</strong>, <strong>25-step Route</strong> for a current parent or <strong>24-step Route</strong> for a historical parent, <strong>Weld Register</strong>, <strong>Material Traceability</strong>, <strong>Inspection History</strong>, <strong>Work and Rework</strong> and <strong>Kelvion Requirements</strong>. The catalog table and saved QA codes keep mixed historical/current scope explicit. A physical spool's <strong>Spool record Excel</strong> shortcut selects that exact item.</p>
      <p>These records show saved Heat/MTR facts, station visits, weld work, testing decisions, cycle and attempt, technician reports, separate QA results, return custody, corrections, failed attempts and repeat work. Shared parent-assembly evidence is identified as shared; missing evidence stays identified. Downloading does not approve work or issue a Job Packet.</p>
      <p>For component quantities, open the whole P.O. or selected assembly in <strong>Production records → Order resources → Component BOM Excel &amp; template</strong> and choose <strong>Download BOM Excel</strong>. All active supported positions can download this scoped workbook. It contains <strong>Assembly summary</strong>, <strong>Bill of materials</strong>, <strong>Spool register</strong> and <strong>Export info</strong>, plus <strong>Setup quantities</strong> when saved requirements exist. It carries the separate P.O., GPN, assembly and spool identity beside each line. Required, assigned, received, prepared and remaining quantities stay separate. Missing plans are visible; unknown quantities are left blank. Actual per-spool quantities are not multiplied again by the required spool count.</p>
      <p><strong>Excel BOM template</strong> creates an editable planning file with the selected order context and blank material rows. Both downloads are offline workbooks: <strong>editing Excel does not update FabTrace</strong>. The <strong>BOM &amp; drawings</strong> window can import reference BOM files or create separate Excel BOMs from an isometric’s spool tables. Enter the approved production requirements in <strong>Spool parts</strong>, then export again for current progress. Downloading a BOM does not issue or transfer a controlled Job Packet.</p>
      <p>An administrator uses <strong>More tools → Export Excel</strong>. The workbook combines production/audit tables with seven Job Packet tables and <strong>Project progress</strong>, <strong>Part progress</strong> and <strong>Job Packet readiness</strong> reports from a read-only database snapshot.</p>
      <p><strong>Spool parts plans</strong>, <strong>Spool part lines</strong>, <strong>Part allocations</strong> and <strong>Spool parts events</strong> retain the required scope and change records. The <strong>Spool parts progress</strong> report calculates required, assigned, received, prepared, short and remaining pieces from the same snapshot.</p>
      <p>Process events, visits and totals include project/work-package/item identity, numeric seconds, decimal hours and calculation time. Sum or pivot elapsed, running and paused durations by process. Open timers are snapshots at export time; export again for later totals.</p>
      <p>File metadata and issued JSON snapshots are included. Binary supporting attachments come from the packet ZIP. The workbook is an export, not a replacement for current in-app reviews, signed decisions or actual transmittal records.</p>`},
    {id:'troubleshooting',title:'14. Resolve the next blocker',summary:'Missing scope, stale reviews, file revisions, conflicts, QR and handover problems.',route:'progress',link:'Review registered project parts',body:`
      <div class="tablewrap"><table><caption>Common symptoms and next actions</caption><thead><tr><th>What you see</th><th>What to check</th></tr></thead><tbody>
      <tr><td>No project or no items</td><td>Start in Orders to create the P.O. and its quantities, or use Production records to explicitly attach earlier work. Open Spool QR labels to review existing copies and permitted generation; saving quantities alone does not register them. Confirm exact parent and project links. A free-text job label is not enrolled automatically.</td></tr>
      <tr><td>Expected packet count differs</td><td>Reconcile approved scope and actual plans. Do not reduce the count to hide missing work.</td></tr>
      <tr><td>Earlier steps not recorded</td><td>Inspect the documented baseline. Do not backfill invented history.</td></tr>
      <tr><td>Source needs confirmation</td><td>QA reviews the current PO, source revisions, quality codes and applicability.</td></tr>
      <tr><td>File superseded / check stale</td><td>Select the correct revision, inspect what changed and obtain a new QA decision.</td></tr>
      <tr><td>100% checks but issue blocked</td><td>Resolve the separately listed physical release, source, scope and child-packet conditions.</td></tr>
      <tr><td>Record changed while a form was open</td><td>Close the form, refresh, review the latest records and reopen the action. Do not resubmit an outdated decision.</td></tr>
      <tr><td>Download but no transfer status</td><td>Record actual dispatch after transfer, then actual acknowledgement for that exact revision.</td></tr>
      <tr><td>QR camera or labels unavailable</td><td>Check HTTPS, camera permission and public URL configuration. Use a hardware scanner or enter the exact ID. Allow print pop-ups.</td></tr>
      <tr><td>Checklist status unavailable</td><td>Retry the read. Do not treat missing or failed responses as completed setup. Contact the administrator if access or service errors persist.</td></tr>
      </tbody></table></div>`},
    {id:'admin',title:'15. Use administrator controls',summary:'Administrative release, custody corrections, employee removal, access and private PIN resets.',route:'admin',link:'Open Admin controls',body:`
      <p>An administrator opens <strong>Admin controls</strong> from the navigation, or chooses <strong>Release as administrator</strong> on an item. Search for the actual item and review its current release, custodian, location and outstanding requirements.</p>
      <p><strong>Release as administrator</strong> records an explicit administrative decision even when ordinary release checks remain incomplete. Enter the reason and any authorization or disposition reference. The item is labelled <strong>Administrative release</strong>; the decision retains the administrator, time and bypassed requirements. Existing weld, inspection, hold and packet records keep their actual status. The progress bars continue to use recorded physical work.</p>
      <p>For a numbered spool, the release positions its traveler at handoff step 16; a current assembly moves to the mandatory shipment Floor handoff at 23. A historical 24-step assembly retains its ready-to-ship position at 23. A component is marked administratively released without claiming its missing preparation steps were completed. The normal checks still apply to later process actions. <strong>Return to work</strong> restores the pre-override production position when available and keeps the earlier release decision. Actual shipment/delivery records are retained.</p>
      <p><strong>Correct custodian / location</strong> fixes the recorded custodian, selected location or work status using the administrator's reason. Its history says administrative correction; it does not claim an employee badge scan. Ordinary handoffs still require the sending and receiving badge identities.</p>
      <p>In <strong>Employees</strong> or <strong>Admin controls → Employee accounts</strong>, choose <strong>Change position</strong>, select a position, enter a reason and save. Select <strong>Administrator</strong> to promote a Handler / Material coordinator. The employee signs in again for the new permissions; their badge, PIN, active state and history stay attached to the same account. Choose <strong>Account controls</strong> for name or active-access changes, a private PIN reset, or <strong>Remove employee</strong>. For removal, review the employee and any current item assignments, enter a reason, then select <strong>Remove employee</strong> to save. Removal stops sign-in and badge handoffs, revokes existing sessions and hides the employee from the normal roster. Their badge identity, welds, inspections and transfers stay traceable. Current item assignments stay recorded; use an explicit custody correction to reassign them.</p><p>Use <strong>Show removed employees → Account controls → Restore employee</strong> to return someone to the roster. Restoration leaves the account <strong>inactive</strong>; use Edit account afterward if access should resume. At least one active administrator must remain. A PIN reset also revokes existing sessions. Private PINs and hashes are never displayed; provide a new PIN privately through the company's approved channel.</p>
      <p>To print employee badges in bulk, open <strong>Employees → Print employee badge sheets</strong> or use the same button in <strong>Admin controls → Employee accounts</strong>. All active employees are selected initially. Keep them selected for the complete roster or choose individuals; searching does not clear other selections. Choose <strong>Print badges</strong>, wait for every QR code to load, then select <strong>Print / Save as PDF</strong> in the print window. Use Letter paper at 100% / Actual size with browser headers and footers turned off. The sheets have several badges per page and cut lines. Each badge uses the current employee name, position, permanent badge ID and existing QR. Inactive and removed employees are excluded. If a badge is no longer available, refresh employees and try again.</p>
      <p>If a record changes while your form is open, refresh and review the latest state before submitting a new decision. Site-management shortcuts open the existing project, audit, shop-location and Excel controls.</p>`}
  ];
  const validSection=value=>topics.some(t=>t.id===value)?value:'';
  function updateUrl(){const q=new URLSearchParams({guide:'1'});if(state.project)q.set('project',state.project);if(state.section)q.set('section',state.section);history.replaceState(null,'','/?'+q.toString());}
  function errorText(error){try{const value=JSON.parse(error.message);if(value.message)return value.message;}catch(_){}return text(error.message||'Project status could not be read.');}
  function roleNote(){const role=text(me?.role||'employee'),label=window.FabPermissions?.label(role)||me?.role_label||role,description=window.FabPermissions?.description(role)||'Your position determines which work controls are available. Ask an administrator to review your assigned position.';return `<p class="fg-role"><strong>Your role: ${esc(label)}.</strong> ${esc(description)} Shared records remain available for traceability. This checklist only reads existing records.</p>`;}
  function stage(id,title,status,label,detail,owner,next,action,tab='') {return {id,title,status,label,detail,owner,next,action,tab};}
  function stages(){
    const p=state.progress||{},d=state.dossier||{},c=p.counts||{},rows=arr(p.items),packets=arr(d.items),cfg=d.config;
    const total=count(c.total_parts),finished=count(c.finished),planning=count(c.planning_needed),hasRows=Array.isArray(p.items)&&total!==null&&rows.length===total;
    const hasPackets=Array.isArray(d.items),planned=hasPackets?packets.length:null,expected=count(cfg?.expected_packets);
    const scopeReady=hasRows&&total>0&&planning===0&&rows.every(r=>r.kind&&r.kind!=='unplanned')&&planned>0;
    const countReady=Boolean(cfg&&expected>0&&planned===expected);
    const sourceReady=Boolean(cfg&&d.source_status==='confirmed');
    const docs=arr(d.documents),currentFiles=docs.filter(v=>v.current===true).length;
    const fabricReady=hasRows&&total>0&&finished===total&&planning===0&&rows.every(r=>r.fabrication_finished===true);
    const currentPackets=packets.filter(v=>v.latest_issue?.current===true).length,packetReady=Boolean(cfg&&planned>0&&currentPackets===planned);
    const latest=d.latest_project_issue||d.latest_issue||null,issueReady=Boolean(latest?.current===true&&scopeReady&&countReady&&sourceReady&&fabricReady&&packetReady&&Array.isArray(d.completion_blockers)&&!d.completion_blockers.length);
    return [
      stage('scope','Register and link the physical scope',scopeReady?'done':'pending',scopeReady?'Registered scope planned':'Needs setup',`${total===null?'Unknown number of':total} registered physical item(s); ${planned===null?'unknown':planned} spool/assembly plan(s); ${planning===null?'unknown number':planning} needing planning. Confirm the complete approved BOM; absent records are not counted.`, 'Shop Foreman / administrator','Review actual item enrollment, structured project assignment and parent/child scope.','tracking'),
      stage('config','Configure the intended packet count',countReady?'done':'pending',countReady?'Declared count matches':'Needs setup',cfg?`Declared expected packets: ${expected===null?'not verified':expected}. Registered spool/assembly plans: ${planned===null?'not verified':planned}. Preparation components do not add to this packet count.`:'No Job Packet configuration is recorded for this project.','Shop Foreman / administrator','Enter the real manufacturer/contact, PO, source reference and full expected spool/assembly count; reconcile any mismatch.','dossier','items'),
      stage('source','Confirm current source applicability',sourceReady?'done':'pending',sourceReady?'Confirmed by QA':'Needs source review',sourceReady?'The server reports a current source/PO applicability review.':'The actual current PO, source revisions, quality codes and applicability need a separate QA confirmation.','Inspector / administrator','Open project document controls and review the actual customer sources.','dossier','items'),
      stage('files','Make controlled files available',currentFiles>0?'done':'pending',currentFiles>0?'Current files available':'Needs setup',`${currentFiles} current uploaded file(s)${Array.isArray(d.documents)?`; ${docs.length} retained revision(s)`: '; file availability is not verified'}. This checks availability only; exact checklist selections and QA decide completeness.`,'Shop Foreman / inspector / administrator','Upload actual shared or item evidence with controlled codes and revisions, then select the correct files on each check.','dossier','documents'),
      stage('fabrication','Finish current fabrication and preparation',fabricReady?'done':'pending',fabricReady?'Registered fabrication finished':'Work / verification remains',`${finished===null?'Unknown':finished} of ${total===null?'unknown':total} registered physical item(s) currently finished. Shipped and delivered items remain included. Zero registered items never mean complete.`,'Production staff; QA for release','Open the actual item, weld or numbered-route blockers and resolve the current work and quality conditions.','progress'),
      stage('packets','Review and issue the current item packets',packetReady?'done':'pending',packetReady?'Registered packets current':'QA review / issue remains',`${currentPackets} of ${planned===null?'unknown':planned} registered spool/assembly packet(s) have a current QA-issued revision. Review percentages alone do not prove issue readiness.`,'Inspector / administrator','Resolve the full checklist and physical/source blockers; issue child packets before the parent assembly.','dossier','items'),
      stage('issue','Issue the completed project revision',issueReady?'done':latest?'historical':'pending',issueReady?'Current project issue':latest?'Review current completion':'Not issued',latest?`Project revision ${text(latest.revision)} is ${issueReady?'current for the registered completion basis':'historical or needs current completion verification'}. ${arr(d.completion_blockers).length} project issue blocker(s) reported.`:'No completed-project revision is recorded. Confirm intended scope and all current item packets before issue.','Inspector / administrator','Resolve project completion blockers and issue a new controlled project revision when ready.','dossier','issues')
    ];
  }
  function stageView(s,index){return `<li class="fg-stage" data-guide-stage="${esc(s.id)}" data-guide-status="${esc(s.status)}"><span class="fg-step" aria-hidden="true">${index+1}</span><div><div class="fg-stage-head"><h3>${esc(s.title)}</h3>${badge(s.status,s.label)}</div><p>${esc(s.detail)}</p><p class="fg-owner"><strong>Owner:</strong> ${esc(s.owner)}</p><p><strong>Next action:</strong> ${esc(s.next)}</p><div class="actions">${button(s.action,s.action==='tracking'?'Open project spool register':s.action==='progress'?'Open project parts':s.tab==='documents'?'Open project files':s.tab==='issues'?'Open issued project packages':'Open project Job Packets',state.project,s.tab)}</div></div></li>`;}
  function transferView(){
    const d=state.dossier||{},latest=d.latest_project_issue||d.latest_issue,current=latest?.current===true?latest:null,events=arr(d.handovers),issues=arr(d.issues);
    return `<section class="fg-card"><h2>Record actual handover and receipt</h2><p>Digital and physical channels are tracked separately against an exact project revision. Follow the approved PO / handover plan; a missing optional channel is not classified as a contract failure.</p><div class="fg-transfer-grid">${['digital','physical'].map(channel=>{
      const transfer=d.transfer_status?.[channel]||{},dispatch=current&&transfer.dispatch&&text(transfer.dispatch.issue_id)===text(current.id)?transfer.dispatch:null;
      const receipt=dispatch&&transfer.receipt&&text(transfer.receipt.dispatch_id)===text(dispatch.id)?transfer.receipt:null;
      const historic=events.filter(e=>e.channel===channel&&(!current||text(e.issue_id)!==text(current.id))),oldDispatch=historic.filter(e=>e.event==='dispatch').at(-1),oldReceipt=oldDispatch&&historic.find(e=>e.event==='receipt'&&text(e.dispatch_id)===text(oldDispatch.id));
      const oldIssue=oldDispatch&&issues.find(i=>text(i.id)===text(oldDispatch.issue_id));
      return `<article class="fg-transfer"><h3>${channel==='digital'?'Digital':'Physical'} packet</h3><p>${current?`Current project revision ${esc(current.revision)}`:'Awaiting a current completed-project issue'}</p><dl><div><dt>Dispatch</dt><dd>${badge(dispatch?'done':'optional',dispatch?'Dispatched':'Not recorded · if required')}${dispatch?`<small>${esc(dispatch.occurred_on)} · ${esc(dispatch.reference)}</small>`:''}</dd></div><div><dt>Receipt</dt><dd>${badge(receipt?'done':'optional',receipt?'Receipt recorded':'Not recorded')}${receipt?`<small>${esc(receipt.occurred_on)} · ${esc(receipt.reference)}</small>`:''}</dd></div></dl>${oldDispatch?`<p class="fg-history"><strong>Historical revision ${esc(oldIssue?.revision??oldDispatch.issue_id)}:</strong> dispatch ${esc(oldDispatch.occurred_on)} · ${esc(oldDispatch.reference)}. ${oldReceipt?'Receipt recorded · '+esc(oldReceipt.reference):'No linked receipt recorded.'} This is history, not current completion or delivery.</p>`:''}</article>`;
    }).join('')}</div><p class="fg-note">Owner: Shop Foreman / inspector / administrator. Download or print, carry out the actual transfer, then record dispatch and later acknowledgement. Product shipment and delivery remain separate in Process flow.</p><div class="actions">${button('dossier','Open handover & receipts',state.project,'handovers')}</div></section>`;
  }
  function attentionView(){
    const packets=arr(state.dossier?.items),rows=arr(state.progress?.items).filter(row=>row.kind==='unplanned'||row.fabrication_finished!==true||packets.some(p=>text(p.item_id)===text(row.id)&&p.latest_issue?.current!==true));
    if(!rows.length)return '';
    return `<section class="fg-card"><h2>Open the records that need attention</h2><p>Showing ${Math.min(rows.length,8)} of ${rows.length} registered item(s) needing planning, fabrication or a current packet. Use Project progress for the complete scope.</p><div class="fg-records">${rows.slice(0,8).map(row=>`<article><h3>${esc(row.id)}</h3>${row.kind==='unplanned'?'<p>Needs structured planning</p>':''}<p class="fg-note">${esc(arr(row.blockers)[0]|| (row.fabrication_finished===true?'Review the current item packet.':'Review current fabrication/preparation.'))}</p><div class="actions">${button('item','Open physical item',row.id)}${button('flow-item','Open process flow',row.id)}${packets.some(p=>text(p.item_id)===text(row.id))?button('packet','Open item packet',row.id):''}</div></article>`).join('')}</div></section>`;
  }
  function projectList(){
    const query=state.projectQuery.trim().toLowerCase(),rows=state.projects.filter(p=>!query||[p.id,p.name,p.client].some(v=>text(v).toLowerCase().includes(query)));
    return `<div class="field fg-project-search"><label for="guideProjectSearch">Find a project</label><input id="guideProjectSearch" type="search" value="${esc(state.projectQuery)}" placeholder="Project ID, name or customer"></div>${rows.length?`<div class="fg-projects">${rows.map(p=>`<article class="fg-card"><span class="fg-eyebrow">${esc(p.id)}</span><h3>${esc(p.name||p.id)}</h3><p>${esc(p.client||'Customer not specified')}</p><p>${count(p.total_parts)===null?'Physical scope not verified':p.total_parts+' registered physical item(s)'} · ${count(p.summary?.items)===null?'Packet scope not verified':p.summary.items+' spool/assembly plan(s)'}</p>${badge(p.configured?'done':'pending',p.configured?'Packet configuration recorded':'Packet setup needed')}<div class="actions">${button('project','Review setup',p.id)}</div></article>`).join('')}</div>`:`<div class="fg-empty"><strong>${state.projects.length?'No projects match the search':'No structured projects are registered'}</strong><p>${state.projects.length?'Clear the project search to see the available projects.':'A Shop Foreman or administrator can create the real project and enroll its actual physical scope.'}</p>${button('tracking','Open Projects & welds')}</div>`}`;
  }
  function setupView(){
    const project=state.progress?.project||state.dossier?.project||state.projects.find(p=>text(p.id)===state.project);
    let html=`<section class="fg-setup" aria-labelledby="guideSetupTitle"><div class="fg-section-head"><div><h2 id="guideSetupTitle">Project setup checklist${state.project?' · '+esc(project?.name||state.project):''}</h2><p>Read the recorded state, identify the responsible role, and open the exact project to take the next action.</p></div>${button('refresh','Refresh setup')}</div><div class="field fg-project-select"><label for="guideProject">Selected project</label><select id="guideProject">${option('','Choose a project',state.project)}${state.project&&!state.projects.some(p=>text(p.id)===state.project)?option(state.project,project?.name||state.project,state.project):''}${state.projects.map(p=>option(text(p.id),`${p.id} · ${p.name||p.id}`,state.project)).join('')}</select></div>`;
    if(state.loading)return html+'<p class="fg-state" role="status">Reading existing project scope and Job Packet records… The operating guide is available below.</p></section>';
    if(state.error)return html+`<div class="fg-error" role="alert"><strong>Setup status could not be verified.</strong><p>${esc(state.error)}</p><p>Missing status is not completion. The operating guide is still available.</p>${button('refresh','Try again')}${state.project?button('project','Choose another project'):''}</div></section>`;
    if(!state.project)return html+projectList()+'</section>';
    const list=stages(),next=list.find(s=>s.status!=='done');
    html+=`<div class="fg-next"><strong>${next?'Next recorded gap: '+esc(next.title):'Current registered completion stages are recorded.'}</strong><p>${next?esc(next.next):'Confirm external scope against the approved BOM and follow the required handover channels below. This checklist does not establish contract acceptance.'}</p></div><ol class="fg-checklist">${list.map(stageView).join('')}</ol>`;
    const blockers=arr(state.dossier?.completion_blockers);
    if(blockers.length)html+=`<details class="fg-card"><summary>Current project issue blockers (${blockers.length})</summary><ul>${blockers.map(v=>`<li>${esc(v)}</li>`).join('')}</ul></details>`;
    return html+transferView()+attentionView()+`<p class="fg-note">${state.progress?.as_of?'Physical progress calculated '+esc(state.progress.as_of)+'. ':''}The two read-only views can change as staff record work; refresh before acting. This checklist never creates records or changes project membership.</p></section>`;
  }
  function guideView(){
    const terms=state.query.trim().toLowerCase().split(/\s+/).filter(Boolean),visible=state.printing?topics:topics.filter(t=>(!state.section||t.id===state.section)&&terms.every(term=>(t.title+' '+t.summary+' '+t.body.replace(/<[^>]*>/g,' ')).toLowerCase().includes(term)));
    return `<section class="fg-operating" aria-labelledby="guideOperatingTitle"><div class="fg-section-head"><div><h2 id="guideOperatingTitle">Operating guide</h2><p>From physical item setup to the final controlled packet and its actual receipt.</p></div>${button('print','Print full guide')}</div><div class="fg-filters"><div class="field fg-search"><label for="guideSearch">Search the guide</label><input id="guideSearch" type="search" value="${esc(state.query)}" placeholder="Try heat, pressure, receipt, QR or 8 MiB"></div><div class="field"><label for="guideSection">Guide topic</label><select id="guideSection">${option('','All topics',state.section)}${topics.map(t=>option(t.id,t.title,state.section)).join('')}</select></div>${button('clear','Clear guide filters')}</div><p class="fg-note fg-result-count" role="status">${visible.length} of ${topics.length} guide topics shown. Print full guide includes all topics and the selected project's loaded checklist.</p>${visible.length?visible.map(t=>`<article class="fg-card fg-topic" id="guide-topic-${esc(t.id)}"><h3>${esc(t.title)}</h3><p class="fg-topic-summary">${esc(t.summary)}</p>${t.body}<div class="actions">${t.route==='admin'&&me?.role!=='admin'?'<span class="fg-note">Administrator access required.</span>':button(t.route,t.link,state.project,t.tab||'')}</div></article>`).join(''):`<div class="fg-empty"><strong>No guide topics match</strong><p>Try a shorter search or choose All topics. Project data is not searched by this field.</p>${button('clear','Clear guide filters')}</div>`}</section>`;
  }
  function render(){
    if(!state.active)return;
    node('guideContent').innerHTML=`<div class="fg-head"><div><div class="fg-eyebrow">CLM · Practical operating reference</div><h1>Guide &amp; setup</h1><p>Set up the real project, follow controlled work and evidence, then issue and hand over the exact completed revision.</p></div><div class="actions">${button('topic','Find a guide topic')}</div></div>${roleNote()}${setupView()}${guideView()}`;
    node('guideContent').setAttribute('aria-busy',String(state.loading));wire();
  }
  function wire(){
    const project=node('guideProject');if(project)project.onchange=()=>selectProject(project.value);
    for(const [id,key] of [['guideProjectSearch','projectQuery'],['guideSearch','query']]){const el=node(id);if(el)el.oninput=()=>{state[key]=el.value;const start=el.selectionStart;render();node(id)?.focus();if(typeof start==='number')node(id)?.setSelectionRange(start,start);};}
    const section=node('guideSection');if(section)section.onchange=()=>{state.section=validSection(section.value);render();updateUrl();};
  }
  async function load(){
    if(!state.active)return;
    const project=state.project;if(state.pending?.project===project)return state.pending.promise;
    const request={project,sequence:++state.sequence,promise:null};state.pending=request;state.loading=true;state.error='';state.progress=null;state.dossier=null;render();
    request.promise=(async()=>{
      const routes=[['Project list','/api/progress/projects'],['Packet project list','/api/dossier/projects']];
      if(project)routes.push(['Physical project scope','/api/progress/projects/'+encodeURIComponent(project)],['Project packet records','/api/dossier/projects/'+encodeURIComponent(project)]);
      try{
        const results=await Promise.allSettled(routes.map(([,url])=>api(url)));
        if(!state.active||request.sequence!==state.sequence)return;
        const failures=results.flatMap((r,i)=>r.status==='rejected'?[routes[i][0]+': '+errorText(r.reason)]:[]);
        if(failures.length)throw Error(failures.join('\n'));
        const values=results.map(r=>r.value);
        if(!Array.isArray(values[0]?.projects)||!Array.isArray(values[1]?.projects))throw Error('The project lists could not be verified. Refresh or ask the administrator to check the service.');
        const projects=new Map();for(const p of [...values[0].projects,...values[1].projects])projects.set(text(p.id),{...projects.get(text(p.id)),...p});
        state.projects=[...projects.values()].sort((a,b)=>text(a.name||a.id).localeCompare(text(b.name||b.id)));
        if(project){state.progress=values[2];state.dossier=values[3];}
      }catch(error){if(!state.active||request.sequence!==state.sequence)return;state.error=errorText(error);state.progress=null;state.dossier=null;}
      finally{if(state.active&&request.sequence===state.sequence){state.pending=null;state.loading=false;render();}}
    })();
    return request.promise;
  }
  async function selectProject(project){state.project=text(project);state.projectQuery='';updateUrl();return load();}
  async function open(options={}){
    if(!me)return;
    show('guidePage');if(typeof stopCloudCamera==='function')stopCloudCamera();current=null;state.active=true;state.project=text(options.project||'');state.section=validSection(text(options.section||''));state.query='';state.projectQuery='';updateUrl();return load();
  }
  function printGuide(){
    if(!state.active||state.printing)return;
    state.printing=true;document.body.classList.add('fg-printing');render();
    try{window.print();}finally{document.body.classList.remove('fg-printing');state.printing=false;render();}
  }
  async function act(action,id,tab){
    if(action==='refresh')return load();if(action==='project')return selectProject(id);
    if(action==='clear'){state.query='';state.section='';render();updateUrl();return;}
    if(action==='topic'){node('guideSearch')?.scrollIntoView({block:'center'});node('guideSearch')?.focus();return;}
    if(action==='print')return printGuide();
    if(action==='tracking')return window.FabTracking.open({project:id||state.project,subproject:'',view:'spools',resetFilters:true});
    if(action==='progress')return window.FabProgress.open({project:id||state.project});
    if(action==='production-progress')return window.FabProductionProgress.open();
    if(action==='order-setup')return window.FabOrderSetup.open();if(action==='orders')return window.FabOrders.open();
    if(action==='parts')return window.FabParts.open({project:id||state.project});
    if(action==='dossier')return window.FabDossier.open({project:id||state.project,tab:['items','documents','issues','handovers'].includes(tab)?tab:'items'});
    if(action==='packet')return window.FabDossier.open({project:state.project,item:id});
    if(action==='item')return openItem(id);
    if(action==='flow-item')return window.FabFlow.open({project:state.project,item:id,resetFilters:true});
    if(action==='flow')return window.FabFlow.open({project:id||state.project,resetFilters:true});
    if(action==='quality')return window.FabQuality.open({project:id||state.project});
    if(action==='admin'&&me?.role==='admin')return window.FabAdmin.open({});
    if(action==='items'){history.replaceState(null,'','/');return listItems();}
  }
  node('guideContent').addEventListener('click',async event=>{const target=event.target.closest('[data-guide-action]');if(!target||target.disabled)return;try{await act(target.dataset.guideAction,target.dataset.guideId||'',target.dataset.guideTab||'');}catch(error){notify(errorText(error));}});
  node('navGuide').onclick=()=>open();
  window.FabGuide={open,refresh:load,cancelPending(){state.active=false;state.sequence++;state.pending=null;state.loading=false;}};
})();



